"""Native CuTe dispatch for the padded BF16 MoE runtime."""


import torch

from kestrel_kernels.moe.errors import FP8_MOE_REQUIRES_COMPACT_CONFIG


def _device_sm(device: torch.device) -> int:
    major, minor = torch.cuda.get_device_capability(device)
    return int(major) * 10 + int(minor)


def _device_supports_cute_moe_bf16(device: torch.device) -> bool:
    return _device_sm(device) in (80, 90, 100, 120)


def _device_supports_cute_moe_pdl(device: torch.device) -> bool:
    sm = _device_sm(device)
    return sm == 90 or sm == 91 or sm == 120


def _resolve_backend(
    *,
    device: torch.device,
    num_tokens: int,
    num_experts: int,
    input_size: int,
    hidden_size: int,
    backend_pref: str = "auto",
    auto_threshold: int = 256,
) -> str:
    del auto_threshold
    if backend_pref not in ("auto", "cute"):
        raise ValueError(
            "Triton is benchmark-only; production BF16 MoE requires native CuTe"
        )
    if not _device_supports_cute_moe_bf16(device):
        raise ValueError(
            f"native BF16 MoE is not implemented for sm_{_device_sm(device)}"
        )

    sm = _device_sm(device)
    if sm in (80, 120) and (input_size % 32 or hidden_size % 32):
        raise ValueError("portable BF16 MoE requires dimensions divisible by 32")
    if sm == 120:
        # The portable warp-MMA implementation is independent of calibrated
        # selectors. Existing tuned backends retain their exact-artifact gate.
        return "portable_warp"

    from kestrel_kernels.cute_moe.config import has_exact_cute_moe_config

    exact_shape = {
        "num_experts": num_experts,
        "hidden_size": input_size,
        "intermediate_size": hidden_size,
        "dtype": "bf16",
    }
    has_exact_shape = has_exact_cute_moe_config(
        **exact_shape, num_tokens=None)
    has_exact_row = has_exact_cute_moe_config(
        **exact_shape, num_tokens=num_tokens)
    if has_exact_shape and has_exact_row:
        return "cute"
    if sm == 80:
        return "portable_warp"
    if not has_exact_shape:
        raise ValueError(
            "native BF16 MoE requires generated shape coverage for "
            f"E{num_experts}/H{input_size}/I{hidden_size}"
        )
    if not has_exact_row:
        raise ValueError(
            "native BF16 MoE requires an exact generated config for "
            f"{num_tokens} tokens"
        )
    raise AssertionError("unreachable exact CuTe MoE dispatch state")


def get_moe_block_m(
    num_tokens: int,
    *,
    num_experts: int,
    input_size: int,
    hidden_size: int,
    backend_pref: str = "auto",
    auto_threshold: int = 256,
    device: torch.device,
) -> int:
    """Return the BLOCK_SIZE_M to use for MoE routing alignment."""
    backend = _resolve_backend(
        device=device, num_tokens=num_tokens,
        num_experts=num_experts, input_size=input_size, hidden_size=hidden_size,
        backend_pref=backend_pref, auto_threshold=auto_threshold,
    )
    if backend == "portable_warp":
        from kestrel_kernels.cute_moe.config import PORTABLE_BF16_WARP_CONFIG
        return PORTABLE_BF16_WARP_CONFIG.block_m
    from kestrel_kernels.cute_moe import get_cute_moe_block_m
    return get_cute_moe_block_m(
        num_tokens, num_experts=num_experts, hidden_size=input_size,
        intermediate_size=hidden_size, dtype="bf16",
    )


def invoke_moe_gemm(
    A: torch.Tensor,
    B: torch.Tensor,
    C: torch.Tensor,
    *,
    B_scale: torch.Tensor | None = None,
    topk_weights: torch.Tensor | None = None,
    sorted_token_ids: torch.Tensor,
    expert_ids: torch.Tensor,
    num_tokens_post_padded: torch.Tensor,
    mul_routed_weight: bool,
    top_k: int,
    num_experts: int,
    input_size: int,
    hidden_size: int,
    allow_tf32: bool = True,
    backend_pref: str = "auto",
    auto_threshold: int = 256,
    config_num_tokens: int | None = None,
) -> None:
    """Dispatch a single MoE GEMM to an exact native CuTe config."""
    if B.dtype == torch.uint8:
        raise ValueError(FP8_MOE_REQUIRES_COMPACT_CONFIG)
    # Accepted for the uniform LegacyPaddedOps backend contract. CUDA padded
    # MoE only supports BF16/FP16/FP32 weights here, so stale FP8 weight scales
    # from prepacked weight containers are intentionally ignored after dtype
    # validation.
    del B_scale

    num_tokens = int(C.shape[0])
    # Routing metadata is built with the prepared handle's block_m. Prefill
    # handles may have capacity > active tokens, so config selection can be
    # pinned to that capacity while launch grids still use the active shape.
    config_tokens = (
        int(config_num_tokens) if config_num_tokens is not None else num_tokens
    )
    del allow_tf32
    backend = _resolve_backend(
        device=A.device, num_tokens=config_tokens,
        num_experts=num_experts, input_size=input_size, hidden_size=hidden_size,
        backend_pref=backend_pref, auto_threshold=auto_threshold,
    )

    from kestrel_kernels.cute_moe import (
        get_cute_moe_routed_config,
        invoke_cute_moe_down,
        invoke_cute_moe_up,
    )

    kind = "down" if mul_routed_weight else "up"
    if backend == "portable_warp":
        from kestrel_kernels.cute_moe.config import PORTABLE_BF16_WARP_CONFIG
        cute_config = PORTABLE_BF16_WARP_CONFIG
    else:
        cute_config = get_cute_moe_routed_config(
            config_tokens,
            num_experts=num_experts,
            hidden_size=input_size,
            intermediate_size=hidden_size,
            dtype="bf16",
        )[kind]
    if cute_config.kernel_type == "tcgen":
        raise ValueError("tcgen MoE uses the compact full-layer runtime path")

    if mul_routed_weight:
        invoke_cute_moe_down(
            A, B, C,
            topk_weights=topk_weights,
            sorted_token_ids=sorted_token_ids,
            expert_ids=expert_ids,
            num_tokens_post_padded=num_tokens_post_padded,
            config=cute_config,
        )
    else:
        invoke_cute_moe_up(
            A, B, C,
            sorted_token_ids=sorted_token_ids,
            expert_ids=expert_ids,
            num_tokens_post_padded=num_tokens_post_padded,
            config=cute_config,
        )
